Sdb* process_elf_version_info(ELFOBJ* bin, Elf_Shdr* shdr, int sz) {
    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    if (!shdr || sz <= 0) {
        sdb_free(sdb);
        return NULL;
    }

    uint8_t* data = elf_get_data(bin, shdr);
    if (!data) {
        sdb_free(sdb);
        return NULL;
    }

    // Parse version definitions
    Elf_Verdef* verdef = (Elf_Verdef*)data;
    for (int i = 0; i < sz / sizeof(Elf_Verdef); i++) {
        if (verdef[i].vd_version != 1) {
            continue;
        }

        char* version_name = elf_get_str(bin, shdr->sh_link, verdef[i].vd_ndx);
        if (!version_name) {
            continue;
        }

        char key[256];
        snprintf(key, sizeof(key), "version.%s", version_name);
        sdb_set(sdb, key, version_name, 0);
    }

    return sdb;
}

Sdb* process_elf_version_info(ELFOBJ* bin, Elf_(Shdr)* shdr, int sz) {
    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    if (!shdr || shdr->sh_type != SHT_GNU_versym) {
        sdb_free(sdb);
        return NULL;
    }

    char* ver_section = elf_get_data(bin, shdr, sz);
    if (!ver_section) {
        sdb_free(sdb);
        return NULL;
    }

    // Assuming helper function elf_get_version_entries() is available in the file context
    VersionEntry* entries = elf_get_version_entries(ver_section, sz);
    if (!entries) {
        sdb_free(sdb);
        return NULL;
    }

    VersionEntry* entry;
    for (entry = entries; entry->name; entry++) {
        if (!sdb_num_put(sdb, entry->name, entry->value, 0)) {
            sdb_free(sdb);
            free(entries);
            return NULL;
        }
    }

    free(entries);
    return sdb;
}

Sdb* elf_process_version_info(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    Sdb *db = sdb_new0();
    if (!db) {
        return NULL;
    }

    // Check if the section header is valid
    if (!shdr || sz <= 0 || !bin) {
        sdb_free(db);
        return NULL;
    }

    // Get version definition data
    Elf_(Versym)* versym = (Elf_(Versym)*)shdr->sh_addr;
    if (!versym) {
        sdb_free(db);
        return NULL;
    }

    for (int i = 0; i < sz; i++) {
        Elf_(Verdef) def;
        def.vd_version = versym[i].ndx;
        def.vd_flags = versym[i].hash;

        char key[128];
        snprintf(key, sizeof(key), "version_entry_%d", i);
        if (!sdb_num_set(db, key, (ut64)def.vd_version, 0)) {
            sdb_free(db);
            return NULL;
        }

        char flags_key[128];
        snprintf(flags_key, sizeof(flags_key), "version_flags_%d", i);
        if (!sdb_num_set(db, flags_key, (ut64)def.vd_flags, 0)) {
            sdb_free(db);
            return NULL;
        }
    }

    return db;
}

Sdb *process_elf_version_info(ELFOBJ *bin, Elf_Shdr *shdr, int sz) {
    Sdb *sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    if (!shdr || sz < sizeof(Elf_Shdr)) {
        sdb_free(sdb);
        return NULL;
    }

    Elf_Verdef *verdef = (Elf_Verdef *)shdr;
    int num_entries = sz / sizeof(Elf_Verdef);

    for (int i = 0; i < num_entries; i++) {
        Elf_Verdef *entry = &verdef[i];
        if (entry->vd_version != 1) {
            continue;
        }

        char *name = elf_strptr(bin, shdr->sh_link, entry->vd_ndx);
        if (!name) {
            sdb_free(sdb);
            return NULL;
        }

        char key[256];
        snprintf(key, sizeof(key), "version.%s", name);
        if (!sdb_num_put(sdb, key, entry->vd_flags, NULL)) {
            sdb_free(sdb);
            return NULL;
        }
    }

    return sdb;
}

Sdb* process_elf_version_definitions(ELFOBJ* bin, Elf_Shdr* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    // Ensure that the section header is valid and contains version info
    if (shdr->sh_type != SHT_GNU_versym && shdr->sh_type != SHT_SUNW_version) {
        sdb_free(sdb);
        return NULL;
    }

    size_t num_entries = shdr->sh_size / sizeof(Elf_Versym);
    Elf_Versym* versym = (Elf_Versym*) elf_getdata(bin, shdr, NULL);
    if (!versym) {
        sdb_free(sdb);
        return NULL;
    }

    for (size_t i = 0; i < num_entries; i++) {
        int version_index = versym[i] & 0x7fff;
        if (version_index == 0) {
            continue;
        }

        char* version_name = elf_get_version(bin, version_index);
        if (!version_name) {
            sdb_free(sdb);
            return NULL;
        }

        char key[64];
        snprintf(key, sizeof(key), "version.%zu", i);
        if (sdb_num_put(sdb, key, version_index, 0) == NULL || sdb_put(sdb, version_name, NULL)) {
            free(version_name);
            sdb_free(sdb);
            return NULL;
        }

        free(version_name);
    }

    return sdb;
}
